    refs:[['MDN：Cache-Control','https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control'],['Amazon CloudFront：简介','https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/Introduction.html'],['七牛云：对象存储','https://developer.qiniu.com/kodo'],['阿里云：什么是对象存储 OSS','https://help.aliyun.com/zh/oss/product-overview/what-is-oss']]
